SELECT * FROM inventory_check


        AND check_no LIKE '%' || #{params.checkNo} || '%'


        AND supply_point_id = #{params.supplyPointId}


        AND check_date >= #{params.startDate}


        AND check_date <= #{params.endDate}


        AND status = #{params.status}


ORDER BY create_time DESC

SELECT COUNT(*) FROM inventory_check
WHERE check_date >= #{startDate}
  AND status = 'completed'

SELECT COALESCE(SUM(diff_count), 0) FROM inventory_check
WHERE check_date >= #{startDate}
  AND status = 'completed'

SELECT COALESCE(SUM(total_items), 0) FROM inventory_check
WHERE check_date >= #{startDate}
  AND status = 'completed'
